def valid(number: str) -> bool:
    """Return whether *number* passes the Luhn check.

    Single spaces between digits are ignored. Leading, trailing, repeated, or
    otherwise misplaced spaces make the input invalid.
    """
    if not isinstance(number, str):
        return False

    if number.startswith(' ') or number.endswith(' ') or '  ' in number:
        return False

    digits = number.replace(' ', '')
    if len(digits) < 2 or not digits.isascii() or not digits.isdigit():
        return False

    total = 0
    for index, char in enumerate(reversed(digits)):
        digit = ord(char) - ord('0')
        if index % 2 == 1:
            digit *= 2
            if digit > 9:
                digit -= 9
        total += digit

    return total % 10 == 0
